-- --- hand-written ------------------------------------------------------------------------------------------

ALTER TABLE close_checklists
  ADD CONSTRAINT ck_close_checklists__submitted CHECK (status = 'open' OR (submitted_at IS NOT NULL AND submitted_by IS NOT NULL)),
  -- §7 step 9 / §8: the reviewer who closes is not the person who submitted the checklist.
  ADD CONSTRAINT ck_close_checklists__closed CHECK (
    (status IN ('closed', 'locked')) = (closed_at IS NOT NULL) AND (closed_by IS NULL OR closed_by IS DISTINCT FROM submitted_by)),
  ADD CONSTRAINT ck_close_checklists__locked CHECK ((status = 'locked') = (locked_at IS NOT NULL AND locked_by IS NOT NULL));
CREATE TRIGGER tg_close_checklists__no_delete BEFORE DELETE ON close_checklists
  FOR EACH ROW EXECUTE FUNCTION tg_forbid_delete();

ALTER TABLE close_tasks
  ADD CONSTRAINT ck_close_tasks__step CHECK (step_no BETWEEN 1 AND 9),
  ADD CONSTRAINT ck_close_tasks__key CHECK (key ~ '^[a-z][a-z0-9_]{1,59}$'),
  ADD CONSTRAINT ck_close_tasks__completed CHECK ((status IN ('done', 'waived')) = (completed_at IS NOT NULL AND completed_by IS NOT NULL)),
  ADD CONSTRAINT ck_close_tasks__waived CHECK (status <> 'waived' OR btrim(coalesce(waived_reason, '')) <> '');
CREATE TRIGGER tg_close_tasks__no_delete BEFORE DELETE ON close_tasks
  FOR EACH ROW EXECUTE FUNCTION tg_forbid_delete();

ALTER TABLE audit_samples
  ADD CONSTRAINT ck_audit_samples__size CHECK (size > 0 AND population_size >= 0 AND jsonb_typeof(selected) = 'array'),
  ADD CONSTRAINT ck_audit_samples__population CHECK (btrim(population) <> '');
CREATE TRIGGER tg_audit_samples__append_only BEFORE UPDATE OR DELETE ON audit_samples
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

ALTER TABLE pbc_exports ADD CONSTRAINT ck_pbc_exports__sha256 CHECK (octet_length(sha256) = 32);
CREATE TRIGGER tg_pbc_exports__append_only BEFORE UPDATE OR DELETE ON pbc_exports
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
